internal sealed class PetMapCanvas:FrameworkElement {
    readonly PetAssets assets;readonly object loadGate=new object();BitmapSource terrain;PetWorld world;List<PetPoint> points=new List<PetPoint>();readonly List<Tuple<Rect,PetPoint>> hits=new List<Tuple<Rect,PetPoint>>();double zoom=1,panX,panY;Point start,oldPan;bool dragging;volatile bool closed;int request;internal bool Portraits=true;internal bool Ready {get{return terrain!=null;}}
    internal PetMapCanvas(PetAssets assets){this.assets=assets;ClipToBounds=true;Focusable=true;Cursor=Cursors.Hand;}
    internal void Load(int id,IEnumerable<PetPoint> markers){points=markers.ToList();PetWorld next;if(!assets.Worlds.TryGetValue(id,out next)){request++;world=null;terrain=null;InvalidateVisual();return;}if(world!=null&&world.Id==id){InvalidateVisual();return;}world=next;terrain=null;zoom=1;panX=panY=0;int generation=++request;InvalidateVisual();
        Task.Factory.StartNew(delegate{lock(loadGate){if(closed||generation!=System.Threading.Interlocked.CompareExchange(ref request,0,0))return null;using(var bitmap=assets.Map(id)){if(bitmap==null||closed||generation!=System.Threading.Interlocked.CompareExchange(ref request,0,0))return null;return SettingsVisual.Bitmap(bitmap);}}}).ContinueWith(task=>{var failure=task.Exception;if(closed||Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke(new Action(delegate{if(closed||generation!=request)return;if(task.Status==TaskStatus.RanToCompletion)terrain=task.Result;else ToolTip="Map image unavailable";InvalidateVisual();}));});
    }
    internal void Markers(IEnumerable<PetPoint> markers){points=markers.ToList();InvalidateVisual();}
    internal void Zoom(double factor){zoom=Math.Max(1,Math.Min(6,zoom*factor));if(zoom==1)panX=panY=0;InvalidateVisual();}
    internal void FocusLocations(){if(terrain==null||points.Count==0)return;double x=points.Average(p=>p.X),y=points.Average(p=>p.Y);zoom=2;var b=ImageRect();panX+=ActualWidth/2-(b.X+x*b.Width);panY+=ActualHeight/2-(b.Y+y*b.Height);InvalidateVisual();}
    Rect ImageRect(){if(terrain==null)return new Rect();double s=Math.Min(ActualWidth/terrain.PixelWidth,ActualHeight/terrain.PixelHeight)*zoom,w=terrain.PixelWidth*s,h=terrain.PixelHeight*s;return new Rect((ActualWidth-w)/2+panX,(ActualHeight-h)/2+panY,w,h);}
    protected override void OnRender(DrawingContext dc){base.OnRender(dc);dc.DrawRectangle(SettingsVisual.Brush("#10171E"),null,new Rect(0,0,ActualWidth,ActualHeight));hits.Clear();if(terrain==null)return;var rect=ImageRect();dc.DrawImage(terrain,rect);var occupied=new HashSet<long>();var outline=new Pen(SettingsVisual.Brush("#173D37"),1.5);foreach(var p in points){double x=rect.X+p.X*rect.Width,y=rect.Y+p.Y*rect.Height;if(x< -20||y< -20||x>ActualWidth+20||y>ActualHeight+20)continue;int cell=Portraits?22:10;long key=((long)(int)(x/cell)<<32)^(uint)(int)(y/cell);if(!occupied.Add(key))continue;double size=Portraits?22:9;var marker=new Rect(x-size/2,y-size/2,size,size);var image=Portraits?assets.PortraitSource(p.Pet):null;dc.DrawEllipse(SettingsVisual.Brush("#67C7B0"),outline,new Point(x,y),size/2+1,size/2+1);if(image!=null)dc.DrawImage(image,marker);hits.Add(Tuple.Create(marker,p));}}
    protected override void OnMouseWheel(MouseWheelEventArgs e){Zoom(e.Delta>0?1.18:1/1.18);e.Handled=true;}
    protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e){dragging=true;start=e.GetPosition(this);oldPan=new Point(panX,panY);CaptureMouse();e.Handled=true;}
    protected override void OnMouseMove(MouseEventArgs e){var at=e.GetPosition(this);if(dragging){panX=oldPan.X+at.X-start.X;panY=oldPan.Y+at.Y-start.Y;InvalidateVisual();}else{var hit=hits.FirstOrDefault(h=>h.Item1.Contains(at));ToolTip=hit==null?null:assets.Name(hit.Item2.Pet)+"\n"+hit.Item2.Variant+(string.IsNullOrEmpty(hit.Item2.Area)?"":"\n"+hit.Item2.Area);}base.OnMouseMove(e);}
    protected override void OnMouseLeftButtonUp(MouseButtonEventArgs e){dragging=false;ReleaseMouseCapture();e.Handled=true;}
    protected override void OnLostMouseCapture(MouseEventArgs e){dragging=false;base.OnLostMouseCapture(e);}
    internal void Release(){closed=true;request++;terrain=null;points.Clear();hits.Clear();}
}
