    internal void FocusPet(int id){if(!service.Assets.Pets.ContainsKey(id))id=service.Snapshot.Pins.FirstOrDefault(p=>service.Assets.Maps(p).Length>0);if(id==0)id=1038;pet=id;loading=true;try{foreach(ComboBoxItem item in pets.Items)if((int)item.Tag==id){pets.SelectedItem=item;break;}int[] available=service.Assets.Maps(id);int preferred=available.Contains(service.Snapshot.Map)?service.Snapshot.Map:available.Contains(owner.Configuration.Pets.AtlasWorld)?owner.Configuration.Pets.AtlasWorld:available.FirstOrDefault();worlds.Items.Clear();foreach(int world in available)worlds.Items.Add(new ComboBoxItem{Content=service.Assets.Worlds[world].name,Tag=world});foreach(ComboBoxItem item in worlds.Items)if((int)item.Tag==preferred){worlds.SelectedItem=item;break;}worlds.IsEnabled=available.Length>1;}finally{loading=false;}LoadMap();RefreshDetails();}
